import {eventTypeOptions, eventType} from "../event-types.js";
import {icon} from "./icons.js";
import {escapeHtml as esc} from "../account.js";
import {documentUrl, fileSize, pendingProposals, folderPath, folderDescendants} from "../documents.js";
import {eventCount, eventTime} from "../events.js";
import {fullDate, parseDate} from "../date.js";
import {recurrenceLabel} from "../recurrence.js";

const plural = count => `${count} document${count > 1 ? "s" : ""}`;
const searchText = value => value.toLocaleLowerCase("fr-CA").normalize("NFD").replace(/[\u0300-\u036f]/g, "");
const importedDate = value => new Intl.DateTimeFormat("fr-CA", {day: "numeric", month: "short", timeZone: "America/Toronto"}).format(new Date(value));
export function documentBadge(document, events) {
  if (document.analysisState === "analysing") return '<span class="document-badge is-working"><span class="document-spinner"></span>Analyse en cours</span>';
  if (document.analysisState === "error") return '<span class="document-badge is-error">Analyse à réessayer</span>';
  if (document.analysisState === "pending") return '<span class="document-badge">PDF enregistré</span>';
  const pending = pendingProposals(document, events).length;
  return `<span class="document-badge ${pending ? "has-proposals" : "is-done"}">${pending ? `${pending} à vérifier` : document.proposals.length ? `${icon("check")}Ajoutés au calendrier` : "Aucun événement détecté"}</span>`;
}
function inspector(document, state) {
  if (!document) return `<aside class="document-inspector inspector-empty"><span class="inspector-placeholder">${icon("document")}</span><h2>Un PDF, tous ses détails.</h2><p>Sélectionne un document pour le consulter et retrouver ses événements.</p></aside>`;
  const pending = pendingProposals(document, state.events);
  const linked = state.events.filter(event => event.source?.documentId === document.id);
  return `<aside class="document-inspector" aria-label="Détails de ${esc(document.name)}"><button class="inspector-back" data-action="document-back">${icon("chevronLeft")}Retour au dossier</button><div class="inspector-heading"><span class="home-eyebrow">APERÇU DU DOCUMENT</span><button class="icon-button" data-action="document-delete" data-document-id="${document.id}" aria-label="Supprimer ${esc(document.name)}">${icon("trash")}</button></div>
    <div class="pdf-preview" data-pdf-preview="${document.id}"><div class="pdf-preview-loading"><span class="document-spinner"></span>Préparation de l’aperçu…</div><a href="${documentUrl(document.id, null, false, document.origin)}" target="_blank" rel="noopener">Ouvrir le PDF ${icon("external")}</a></div>
    <h2 class="inspector-name">${esc(document.name)}</h2><p class="document-meta">PDF <span>·</span> ${fileSize(document.size)} <span>·</span> Ajouté le ${esc(importedDate(document.createdAt))}</p>
    ${documentLocation(document, state)}${document.summary ? `<p class="document-summary">${esc(document.summary)}</p>` : ""}
    ${document.analysisError ? `<p class="document-analysis-error" role="status">${esc(document.analysisError)}</p>` : ""}
    <div class="inspector-events"><div class="inspector-section-heading">${icon("calendar")}<h3>Événements</h3><span>${linked.length}</span></div>
      ${pending.length ? `<p>${eventCount(pending.length)} à vérifier avant l’ajout.</p><button class="primary-button document-review-button" data-action="document-review" data-document-id="${document.id}">${icon("sparkles")}Vérifier les événements</button>` : document.analysisState === "ready" ? `<p>${linked.length ? "Le document reste lié à chaque événement." : "Aucun événement à ajouter. Ton PDF reste disponible ici."}</p>` : `<p>${document.analysisState === "analysing" ? "Recherche des dates et des rendez-vous dans ce PDF." : "Recherche les dates et les rendez-vous."}</p><button class="secondary-button" data-action="document-analyze" data-document-id="${document.id}" ${state.documentJobs.some(job => job.documentId === document.id && ["uploading", "analysing", "waiting"].includes(job.status)) || !state.aiAvailable ? "disabled" : ""}>${icon("sparkles")}${document.analysisState === "pending" ? "Rechercher des événements" : "Réessayer l’analyse"}</button>${!state.aiAvailable ? '<p class="document-ai-note">La recherche sera disponible une fois l’analyse configurée.</p>' : ""}`}
      ${linked.length ? `<div class="document-linked-events">${linked.map(event => `<button data-action="open-event" data-event-id="${event.id}"><span>${esc(fullDate(parseDate(event.date), false))}</span><strong>${esc(event.title)}</strong>${icon("chevronRight")}</button>`).join("")}</div>` : ""}
    </div><a class="document-download" href="${documentUrl(document.id, null, true)}">${icon("download")}Télécharger l’original</a></aside>`;
}
function folderMenu(folder) {
  return `<details class="folder-menu"><summary aria-label="Actions pour ${esc(folder.name)}">${icon("more")}</summary><div><button data-action="folder-rename" data-folder-id="${folder.id}">${icon("edit")}Renommer</button><button data-action="folder-move" data-folder-id="${folder.id}">${icon("folder")}Déplacer</button><button data-action="folder-delete" data-folder-id="${folder.id}">${icon("trash")}Supprimer</button></div></details>`;
}
function breadcrumbs(folders, id, action = "folder-open") {
  const path = folderPath(folders, id);
  return `<nav class="document-breadcrumbs" aria-label="Emplacement des documents"><button data-action="${action}" data-folder-id="" ${!id ? 'aria-current="page"' : ""}>${icon("folder")}Documents</button>${path.map((folder, index) => `${icon("chevronRight")}<button data-action="${action}" data-folder-id="${folder.id}" ${index === path.length - 1 ? 'aria-current="page"' : ""}>${esc(folder.name)}</button>`).join("")}</nav>`;
}
function documentLocation(document, state) {
  const path = folderPath(state.documentFolders || [], document.folderId);
  return `<div class="inspector-location"><span>${icon("folder")}<span>${esc(path.map(folder => folder.name).join(" / ") || "Documents")}</span></span><button data-action="document-move" data-document-id="${document.id}">Déplacer</button></div>`;
}
function folderCard(folder, state, globalSearch) {
  const children = state.documentFolders.filter(row => row.parentId === folder.id).length;
  const files = state.documents.filter(row => row.folderId === folder.id).length;
  const path = folderPath(state.documentFolders, folder.parentId).map(row => row.name).join(" / ") || "Documents";
  return `<article class="document-folder-card"><button class="document-folder-open" data-action="folder-open" data-folder-id="${folder.id}"><span class="folder-symbol">${icon("folder")}</span><span><strong>${esc(folder.name)}</strong><small>${globalSearch ? esc(path) : `${children ? `${children} sous-dossier${children > 1 ? "s" : ""}${files ? " · " : ""}` : ""}${files ? plural(files) : children ? "" : "Dossier vide"}`}</small></span></button>${folderMenu(folder)}</article>`;
}
function documentRow(document, selected, state, globalSearch) {
  const path = folderPath(state.documentFolders, document.folderId).map(row => row.name).join(" / ") || "Documents";
  return `<button class="document-row ${selected?.id === document.id ? "is-selected" : ""}" data-action="document-select" data-document-id="${document.id}" aria-pressed="${selected?.id === document.id}"><span class="pdf-file-icon">${icon("document")}<span>PDF</span></span><span class="document-row-copy"><strong>${esc(document.name)}</strong><span class="document-meta">${fileSize(document.size)} <span>·</span> ${esc(importedDate(document.createdAt))}${globalSearch ? ` <span>·</span> ${esc(path)}` : ""}</span>${documentBadge(document, state.events)}</span>${icon("chevronRight", "document-row-arrow")}</button>`;
}
export function renderDocuments(state) {
  const query = searchText(state.documentQuery.trim());
  const globalSearch = !!query || state.documentFilter === "pending";
  const currentFolder = state.documentFolders.find(folder => folder.id === state.currentFolderId);
  const localDocuments = state.documents.filter(document => (document.folderId ?? null) === state.currentFolderId);
  const filtered = state.documents.filter(document => (globalSearch || (document.folderId ?? null) === state.currentFolderId) && (!query || searchText(`${document.name} ${document.summary}`).includes(query)) && (state.documentFilter === "all" || pendingProposals(document, state.events).length));
  const folders = state.documentFolders.filter(folder => state.documentFilter === "all" && (query ? searchText(folder.name).includes(query) : folder.parentId === state.currentFolderId)).sort((a, b) => a.name.localeCompare(b.name, "fr-CA", {numeric: true}));
  const selected = filtered.find(document => document.id === state.selectedDocumentId) || null;
  const pending = state.documents.filter(document => pendingProposals(document, state.events).length).length;
  const jobs = state.documentJobs;
  const firstUse = !state.documents.length && !state.documentFolders.length && !globalSearch;
  return `<section class="documents-page" aria-labelledby="documents-title"><header class="documents-intro"><div><p class="home-eyebrow">TA BIBLIOTHÈQUE, À TON RYTHME</p><h1 id="documents-title" tabindex="-1">Documents</h1><p>Organise tes PDF par dossier. Retrouve les dates et les moments qui comptent.</p></div><div class="documents-header-actions"><button class="secondary-button" data-action="folder-create" ${state.documentsStatus !== "ready" ? "disabled" : ""}>${icon("folderPlus")}Nouveau dossier</button><button class="primary-button document-add-button" data-action="document-add">${icon("plus")}Ajouter des PDF</button></div></header>
    ${jobs.length ? `<section class="document-import-jobs" aria-label="Imports de documents" aria-live="polite"><div class="import-jobs-heading"><strong>Import des documents</strong>${jobs.every(job => ["done", "error"].includes(job.status)) ? '<button data-action="document-jobs-dismiss" aria-label="Masquer les imports terminés">Fermer</button>' : '<span>Tu peux continuer à utiliser Tempo</span>'}</div>${jobs.map(job => `<div class="import-job"><span class="${["waiting", "uploading", "analysing"].includes(job.status) ? "document-spinner" : "import-job-symbol"}">${job.status === "done" ? icon("check") : job.status === "error" ? "!" : ""}</span><span><strong>${esc(job.name)}</strong><span>${esc(job.message || ({waiting: "En attente", uploading: "Enregistrement du PDF…", analysing: "PDF enregistré · recherche des événements…", done: "PDF enregistré"})[job.status])}</span></span>${job.status === "error" && job.retryable ? `<button data-action="document-job-retry" data-job-id="${job.id}">Réessayer</button>` : ""}</div>`).join("")}</section>` : ""}
    ${state.documentsStatus === "error" ? `<div class="documents-load-error" role="alert"><span>${esc(state.documentsError)}</span><button class="secondary-button" data-action="documents-retry">Réessayer</button></div>` : ""}
    ${state.documentsStatus === "loading" && !state.documents.length ? '<div class="documents-loading" role="status"><span class="document-spinner"></span>Chargement de ta bibliothèque…</div>' : `<div class="document-library-layout ${selected && state.documentDetailsOpen ? "has-document-detail" : ""}"><section class="document-library" aria-label="Bibliothèque de PDF"><div class="document-location-bar">${breadcrumbs(state.documentFolders, state.currentFolderId)}${currentFolder ? folderMenu(currentFolder) : ""}</div><div class="document-library-toolbar"><div class="document-filters" role="group" aria-label="Filtrer les documents"><button data-action="document-filter-all" aria-pressed="${state.documentFilter === "all"}">Tous <span>${localDocuments.length}</span></button><button data-action="document-filter-pending" aria-pressed="${state.documentFilter === "pending"}">À vérifier ${pending ? `<span>${pending}</span>` : ""}</button></div><label class="document-search">${icon("search")}<input id="document-search" type="search" placeholder="Rechercher" aria-label="Rechercher dans la bibliothèque" value="${esc(state.documentQuery)}"/></label></div>
      <div class="document-list"><div class="document-list-heading"><h2 id="document-location-title" tabindex="-1">${globalSearch ? query ? "Résultats de recherche" : "À vérifier" : esc(currentFolder?.name || "Tous les documents")}</h2><span>${globalSearch ? "Toute la bibliothèque" : `${folders.length ? `${folders.length} dossier${folders.length > 1 ? "s" : ""} · ` : ""}${plural(filtered.length)}`}</span></div>
      ${folders.length ? `<div class="document-folder-grid">${folders.map(folder => folderCard(folder, state, !!query)).join("")}</div>` : ""}
      ${filtered.length ? `<div class="document-file-list">${filtered.map(document => documentRow(document, selected, state, globalSearch)).join("")}</div>` : !folders.length ? `<div class="${firstUse ? "document-empty document-dropzone" : "documents-no-results"}" ${firstUse ? "data-document-dropzone" : ""}>${icon(globalSearch ? "search" : currentFolder ? "folder" : "document")}<h2>${globalSearch ? query ? "Aucun résultat" : "Tout est à jour" : currentFolder ? "Un dossier prêt à remplir." : "Une place pour chaque document."}</h2><p>${globalSearch ? query ? "Essaie un autre nom ou un mot du document." : "Aucun événement en attente de vérification." : currentFolder ? "Ajoute des PDF ou crée un sous-dossier pour tout garder au même endroit." : "Crée ton premier dossier ou ajoute des PDF.<br/>On repère les événements, tu choisis ceux à ajouter."}</p>${!globalSearch ? `<button class="primary-button" data-action="document-add">${icon("upload")}Choisir des PDF</button>` : ""}</div>` : ""}</div>
      ${!globalSearch ? `<div class="document-dropzone compact" data-document-dropzone><span>${icon("upload")}Glisse des PDF ${currentFolder ? "dans ce dossier" : "ici"}</span><button data-action="document-add">Parcourir les fichiers</button></div>` : ""}</section>${inspector(selected, state)}</div>`}
    <footer class="documents-footnote"><span>${icon("folder")}${state.documentFolders.length} dossier${state.documentFolders.length > 1 ? "s" : ""} <span>·</span> ${plural(state.documents.length)} dans ta bibliothèque</span><span>PDF · 10 Mo par fichier</span></footer><p class="document-privacy">Les PDF sont enregistrés dans ton compte HomeLab et transmis lors de la recherche d’événements. Tu valides chaque ajout au calendrier.</p>
    <div class="document-drag-overlay" aria-hidden="true">${icon("upload")}Dépose tes PDF ${currentFolder ? `dans « ${esc(currentFolder.name)} »` : "pour les ajouter"}</div></section>`;
}
export function folderNameDialog(folder, folders, parentId) {
  const path = folderPath(folders, parentId).map(row => row.name).join(" / ") || "Documents";
  return `<dialog class="app-dialog document-folder-dialog" aria-labelledby="folder-dialog-title"><form id="folder-name-form"><header class="dialog-heading"><div><span class="event-dialog-eyebrow">ORGANISER LA BIBLIOTHÈQUE</span><h2 id="folder-dialog-title">${folder ? "Renommer le dossier" : "Nouveau dossier"}</h2></div><button type="button" class="icon-button" data-action="document-dialog-close" aria-label="Fermer">${icon("close")}</button></header><p class="dialog-description">${folder ? "Choisis un nom facile à retrouver." : `Ce dossier sera créé dans ${esc(path)}.`}</p><label class="folder-name-field" for="folder-name">Nom du dossier<input id="folder-name" name="name" maxlength="120" required autocomplete="off" placeholder="Ex. Cours, Voyages, Personnel" value="${esc(folder?.name || "")}"/></label><p id="document-dialog-error" class="event-error" role="alert" tabindex="-1" hidden></p><div class="dialog-actions"><button type="button" class="secondary-button" data-action="document-dialog-close">Annuler</button><button type="submit" class="primary-button">${folder ? "Enregistrer" : "Créer le dossier"}</button></div></form></dialog>`;
}
export function moveDialogContent(item, type, folders, destinationId) {
  const excluded = type === "folder" ? folderDescendants(folders, item.id) : new Set();
  const children = folders.filter(folder => folder.parentId === destinationId && !excluded.has(folder.id)).sort((a, b) => a.name.localeCompare(b.name, "fr-CA", {numeric: true}));
  const original = type === "folder" ? item.parentId : item.folderId ?? null;
  const destination = folders.find(folder => folder.id === destinationId);
  return `<header class="dialog-heading"><div><span class="event-dialog-eyebrow">ORGANISER LA BIBLIOTHÈQUE</span><h2 id="folder-dialog-title">Déplacer ${type === "folder" ? "le dossier" : "le PDF"}</h2></div><button class="icon-button" data-action="document-dialog-close" aria-label="Fermer">${icon("close")}</button></header><div class="move-item">${icon(type === "folder" ? "folder" : "document")}<strong>${esc(item.name)}</strong></div><p class="dialog-description">Choisis un dossier de destination, puis confirme le déplacement.</p><div class="folder-destination-browser">${breadcrumbs(folders, destinationId, "folder-move-browse")}<div class="folder-destination-list" aria-label="Dossiers de destination">${children.length ? children.map(folder => `<button data-action="folder-move-browse" data-folder-id="${folder.id}">${icon("folder")}<span>${esc(folder.name)}</span>${icon("chevronRight")}</button>`).join("") : '<p>Aucun sous-dossier à cet emplacement.</p>'}</div></div><p class="move-destination" id="move-destination" tabindex="-1">Destination : <strong>${esc(destination?.name || "Documents")}</strong></p><p id="document-dialog-error" class="event-error" role="alert" tabindex="-1" hidden></p><div class="dialog-actions"><button class="secondary-button" data-action="document-dialog-close">Annuler</button><button class="primary-button" data-action="folder-move-confirm" ${original === destinationId ? "disabled" : ""}>${icon("folder")}Déplacer ici</button></div>`;
}
export function moveItemDialog(item, type, folders, destinationId) {
  return `<dialog class="app-dialog document-folder-dialog document-move-dialog" aria-labelledby="folder-dialog-title">${moveDialogContent(item, type, folders, destinationId)}</dialog>`;
}
export function deleteFolderDialog(folder) {
  return `<dialog class="app-dialog document-folder-dialog" aria-labelledby="folder-dialog-title"><header class="dialog-heading"><h2 id="folder-dialog-title">Supprimer ce dossier?</h2><button class="icon-button" data-action="document-dialog-close" aria-label="Fermer">${icon("close")}</button></header><div class="move-item">${icon("folder")}<strong>${esc(folder.name)}</strong></div><p class="dialog-description">Seuls les dossiers vides peuvent être supprimés. Déplace d’abord les PDF et les sous-dossiers qu’il contient.</p><p id="document-dialog-error" class="event-error" role="alert" tabindex="-1" hidden></p><div class="dialog-actions"><button class="secondary-button" data-action="document-dialog-close">Annuler</button><button class="danger-button" data-action="folder-delete-confirm">Supprimer le dossier</button></div></dialog>`;
}
function proposalRow(document, proposal, state) {
  const event = proposal.event;
  const added = state.events.some(event => event.source?.documentId === document.id && event.source.proposalId === proposal.id);
  const prefix = `proposal-${proposal.id}`;
  return `<article class="document-proposal ${added ? "is-added" : ""}" data-proposal-id="${proposal.id}" data-document-id="${document.id}"><div class="proposal-heading"><input id="${prefix}-select" type="checkbox" class="proposal-checkbox" aria-label="Ajouter ${esc(event.title)}" ${added ? "disabled" : "checked"}/><label for="${prefix}-select"><strong>${esc(event.title)}</strong><span>${esc(fullDate(parseDate(event.date)))}${event.endDate !== event.date ? ` → ${esc(fullDate(parseDate(event.endDate)))}` : ""} <span>·</span> ${esc(eventTime(event, state.preferences.timeFormat))}</span></label>${added ? `<span class="proposal-added">${icon("check")}Ajouté</span>` : ""}</div>
    <div class="proposal-source"><a href="${documentUrl(document.id, proposal.page, false, document.origin)}" target="_blank" rel="noopener">${icon("document")}${proposal.page ? `Page ${proposal.page}` : "Voir le PDF"}${icon("external")}</a>${event.recurrence ? `<span>${esc(recurrenceLabel(event.recurrence))}</span>` : ""}${eventType(event, state.eventTypes) ? `<span>${esc(eventType(event, state.eventTypes).name)}</span>` : ""}</div>
    ${proposal.note ? `<p class="proposal-note">${esc(proposal.note)}</p>` : ""}
    ${added ? "" : `<details class="proposal-editor"><summary>Modifier les détails ${icon("edit")}</summary><div class="proposal-fields"><label for="${prefix}-title">Titre<input id="${prefix}-title" name="title" value="${esc(event.title)}" maxlength="160" required/></label><label for="${prefix}-type">Type d’événement<select id="${prefix}-type" name="typeId">${eventTypeOptions(state.eventTypes, event.typeId)}</select></label><label class="proposal-all-day"><input name="allDay" type="checkbox" ${event.allDay ? "checked" : ""}/>Toute la journée</label><div class="proposal-date-fields"><label for="${prefix}-date">Date de début<input id="${prefix}-date" name="date" type="date" value="${event.date}" min="0001-01-01" max="9999-12-31" required/></label><label for="${prefix}-endDate">Date de fin<input id="${prefix}-endDate" name="endDate" type="date" value="${event.endDate}" min="${event.date}" max="9999-12-31" required/></label><label class="proposal-time" for="${prefix}-start" ${event.allDay ? "hidden" : ""}>Heure de début<input id="${prefix}-start" name="startTime" type="time" value="${event.startTime || "09:00"}" ${event.allDay ? "disabled" : "required"}/></label><label class="proposal-time" for="${prefix}-end" ${event.allDay ? "hidden" : ""}>Heure de fin<input id="${prefix}-end" name="endTime" type="time" value="${event.endTime || "10:00"}" ${event.allDay ? "disabled" : "required"}/></label></div><label for="${prefix}-description">Description<textarea id="${prefix}-description" name="description" rows="2" maxlength="4000">${esc(event.description)}</textarea></label>${event.recurrence ? '<p>Les changements s’appliqueront à toute la série. La répétition pourra être ajustée dans le calendrier.</p>' : ""}</div></details>`}</article>`;
}
export function reviewDocumentsDialog(documents, state) {
  const count = documents.reduce((count, document) => count + pendingProposals(document, state.events).length, 0);
  return `<dialog class="app-dialog document-review-dialog" aria-labelledby="document-review-title" aria-describedby="document-review-description"><form id="document-review-form" novalidate><header class="dialog-heading"><div><span class="event-dialog-eyebrow">${icon("sparkles")}REPÉRÉS DANS TES PDF</span><h2 id="document-review-title">Des moments à prévoir.</h2></div><button type="button" class="icon-button" data-action="document-dialog-close" aria-label="Fermer la revue">${icon("close")}</button></header><p class="dialog-description" id="document-review-description">${eventCount(count)} proposé${count > 1 ? "s" : ""}. Vérifie les dates et choisis ce qui rejoint ton calendrier.</p><div class="document-review-scroll"><div class="review-selection-toolbar"><label><input id="proposal-select-all" type="checkbox" checked/>Tout sélectionner</label><span>Heure de Toronto</span></div>${documents.map(document => `<section class="proposal-document-group"><header>${icon("document")}<h3>${esc(document.name)}</h3><a href="${documentUrl(document.id, null, false, document.origin)}" target="_blank" rel="noopener" aria-label="Ouvrir ${esc(document.name)}">${icon("external")}</a></header>${document.summary ? `<p class="review-document-summary">${esc(document.summary)}</p>` : ""}${document.proposals.map(proposal => proposalRow(document, proposal, state)).join("")}</section>`).join("")}</div><p id="document-dialog-error" class="event-error" role="alert" tabindex="-1" hidden></p><footer class="document-review-footer"><p>Les PDF restent dans ta bibliothèque.<br/><span>Tu pourras reprendre cette revue plus tard.</span></p><div><button type="button" class="secondary-button" data-action="document-dialog-close">Plus tard</button><button id="document-import-events" type="submit" class="primary-button">Ajouter ${count} événement${count > 1 ? "s" : ""} ${icon("check")}</button></div></footer></form></dialog>`;
}
export function deleteDocumentDialog(document, count) {
  return `<dialog class="app-dialog document-delete-dialog" aria-labelledby="document-delete-title"><header class="dialog-heading"><h2 id="document-delete-title">Supprimer ce PDF?</h2><button class="icon-button" data-action="document-dialog-close" aria-label="Fermer">${icon("close")}</button></header><div class="delete-document-file">${icon("document")}<strong>${esc(document.name)}</strong></div><p class="dialog-description">Le PDF et ses propositions seront supprimés de ta bibliothèque.${count ? ` Les ${eventCount(count)} déjà ajouté${count > 1 ? "s" : ""} resteront au calendrier, avec une indication que le document a été supprimé.` : ""}</p><p id="document-dialog-error" class="event-error" role="alert" tabindex="-1" hidden></p><div class="dialog-actions"><button class="secondary-button" data-action="document-dialog-close">Garder le PDF</button><button class="danger-button" data-action="document-delete-confirm">Supprimer le PDF</button></div></dialog>`;
}
